using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class BirminghamMoorSt : LayoutBase
{
    public BirminghamMoorSt()
    {
        Name = LayoutNamesEnums.BirminghamMoorSt;
        Description = "Birmingham Moor Street was originally built as an entry to the 2007 DEMU Minories Challenge, and was subsequently enlarged and entered for the Scalefour Society's Diesel and Electric Layout Challenge, where it was awarded a Highly Commended certificate. The layout represents the terminus side of Moor Street station in central Birmingham, which opened in 1909 and handled suburban services to the south of the city, Leamington Spa and Stratford-upon-Avon until it was replaced by the current through station when Snow Hill re-opened in 1987. It can be operated either in the transition period between steam and diesel traction or in the British Rail corporate era of the late 1970s and early 1980s. In the earlier era most suburban services are in the hands of DMUs but some steam hauled trains are still to be seen, and freight and parcels trains reverse here in order to use the connection to the nearby goods depot. In the later era suburban services are entirely in the hands of DMUs, and the builders have imagined that the goods depot has not closed, so freight and parcels trains can also be seen.";
    }
}
